{
  "headline": "FDA's records trace our supply to a plant classified OAI 1530 days before the posting",
  "headline_cites": ["D5"],
  "sentences": [
    {
      "text": "FDA first posted the remifentanil hydrochloride shortage on 2022-06-28 and it remains current as of 2026-10-21.",
      "cites": ["E24"]
    },
    {
      "text": "The shortage lists Fresenius Kabi USA, LLC, Hikma Pharmaceuticals USA, Inc., and Mylan Institutional, a Viatris Company as affected manufacturers.",
      "cites": ["E21", "E22", "E23"]
    },
    {
      "text": "Our 2 mg/2 mL, 5 mL vials (NDC 00143939210) are labeled by Hikma Pharmaceuticals USA Inc. and manufactured at Hospira, Inc. (FEI 1925262) and Navinta LLC (FEI 3004375014).",
      "cites": ["E1", "E2", "E14", "E20"]
    },
    {
      "text": "FDA inspection 976095 at Hospira, Inc. ended 2016-06-08 and was classified OAI, with the classification known on 2016-09-06.",
      "cites": ["E8"]
    },
    {
      "text": "FDA's OAI classification letter to Navinta LLC is dated 2018-04-20, 1530 days before FDA posted the shortage on 2022-06-28.",
      "cites": ["D5"]
    },
    {
      "text": "FDA inspection 1064827 at Hospira, Inc. ended 2018-08-15 and was classified OAI, with the classification letter dated 2020-04-22, 797 days before the shortage posting.",
      "cites": ["E10", "D4"]
    },
    {
      "text": "Transfer 16 vials of 2 mg/2 mL, 5 mL from Corvale General to Corvale Lakeside; Corvale General has 16.5 days on hand and can spare 16 vials while keeping 14 days, and Corvale Lakeside has 6.8 days and would reach 14 days.",
      "cites": ["D1", "D2", "D7"]
    }
  ]
}
